      "section": "2",
      "question": "<p><strong>प्र.४३) सोबतच्या आकृतीत एकूण त्रिकोणांची संख्या किती आहे?</strong></p><div style='text-align:center;margin:10px 0;'><svg width=\"180\" height=\"160\" viewBox=\"0 0 180 160\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- 5 pointed star -->\n  <polygon points=\"90,15 112,60 165,65 125,100 138,150 90,122 42,150 55,100 15,65 68,60\" fill=\"none\" stroke=\"#333\" stroke-width=\"2\"/>\n  <line x1=\"90\" y1=\"15\" x2=\"138\" y2=\"150\" stroke=\"#333\" stroke-width=\"1.5\"/>\n  <line x1=\"138\" y1=\"150\" x2=\"15\" y2=\"65\" stroke=\"#333\" stroke-width=\"1.5\"/>\n  <line x1=\"15\" y1=\"65\" x2=\"165\" y2=\"65\" stroke=\"#333\" stroke-width=\"1.5\"/>\n  <line x1=\"165\" y1=\"65\" x2=\"42\" y2=\"150\" stroke=\"#333\" stroke-width=\"1.5\"/>\n  <line x1=\"42\" y1=\"150\" x2=\"90\" y2=\"15\" stroke=\"#333\" stroke-width=\"1.5\"/>\n</svg></div>",
      "question_text": "<p><strong>प्र.४३) सोबतच्या आकृतीत एकूण त्रिकोणांची संख्या किती आहे?</strong></p><div style='text-align:center;margin:10px 0;'><svg width=\"180\" height=\"160\" viewBox=\"0 0 180 160\" xmlns=\"http://www.w3.org/2000/svg\">\n  <!-- 5 pointed star -->\n  <polygon points=\"90,15 112,60 165,65 125,100 138,150 90,122 42,150 55,100 15,65 68,60\" fill=\"none\" stroke=\"#333\" stroke-width=\"2\"/>\n  <line x1=\"90\" y1=\"15\" x2=\"138\" y2=\"150\" stroke=\"#333\" stroke-width=\"1.5\"/>\n  <line x1=\"138\" y1=\"150\" x2=\"15\" y2=\"65\" stroke=\"#333\" stroke-width=\"1.5\"/>\n  <line x1=\"15\" y1=\"65\" x2=\"165\" y2=\"65\" stroke=\"#333\" stroke-width=\"1.5\"/>\n  <line x1=\"165\" y1=\"65\" x2=\"42\" y2=\"150\" stroke=\"#333\" stroke-width=\"1.5\"/>\n  <line x1=\"42\" y1=\"150\" x2=\"90\" y2=\"15\" stroke=\"#333\" stroke-width=\"1.5\"/>\n</svg></div>",
