      "explanation": "<p><strong>स्पष्टीकरण:</strong> पंचकोनी ताऱ्यामध्ये (५-pointed star) बाहेरचे ५ लहान त्रिकोण आणि प्रत्येक शिरोबिंदूपासून तयार होणारे ५ मोठे त्रिकोण मिळून एकूण <strong>१० त्रिकोण</strong> असतात.</p>",
