      "question": "<p><strong>प्र.४७) मे महिन्याच्या १५ तारखेस गुरुवार आला असेल, तर त्या महिन्यात कोणता वार पाच वेळा येणार नाही?</strong></p>",
      "question_text": "<p><strong>प्र.४७) मे महिन्याच्या १५ तारखेस गुरुवार आला असेल, तर त्या महिन्यात कोणता वार पाच वेळा येणार नाही?</strong></p>",
