      "answer": 0,
      "correct_option": "1",
      "explanation": "<p><strong>स्पष्टीकरण:</strong> 'किमान दोन कला' म्हणजे २ किंवा ३ कलांमध्ये असणाऱ्या सर्व व्यक्तींची बेरीज:<br>= (गायन व वादन) + (गायन व नृत्य) + (वादन व नृत्य) + (तिन्ही कला)<br>= ५ + १५ + ६ + १३ = <strong>३९ व्यक्ती</strong>.</p>",
