      "question_text": "<p><strong>प्र.५२) पुढील प्रश्नात प्रश्नचिन्हाच्या जागी कोणती संख्या येईल?</strong></p><table border=\"1\" cellpadding=\"8\" style=\"border-collapse:collapse;margin:10px auto;text-align:center;font-size:16px;font-weight:bold;\">\n  <tr><td style=\"width:50px;\">१७</td><td style=\"width:50px;\">८१</td><td style=\"width:50px;\">३३</td></tr>\n  <tr><td style=\"background:#fff9c4;color:#d32f2f;\">?</td><td>४९</td><td>६५</td></tr>\n  <tr><td>४१</td><td>७३</td><td>२५</td></tr>\n</table>",
