      "subject": "बुद्धिमत्ता चाचणी",
      "section": "2",
      "question": "<p><strong>प्रश्न क्रमांक ५५ व ५६ साठी सूचना:</strong> सारणीतील अक्षरे व चिन्हे:<br>ज(&#9698;), य(&#9632;), श(&#8856;), ह(&#9651;), प(&#9675;), र(&times;), ग(+), स(-), ण(&#9633;), ड(&#9746;), काना(&#9863;), वेलांटी(&#9723;), ऊ कार(&#9661;), अनुस्वार(&darr;)</p><p><strong>प्र.५५) हरणाच्या पिल्लाचे नाव कसे लिहाल?</strong></p>",
      "question_text": "<p><strong>प्रश्न क्रमांक ५५ व ५६ साठी सूचना:</strong> सारणीतील अक्षरे व चिन्हे:<br>ज(&#9698;), य(&#9632;), श(&#8856;), ह(&#9651;), प(&#9675;), र(&times;), ग(+), स(-), ण(&#9633;), ड(&#9746;), काना(&#9863;), वेलांटी(&#9723;), ऊ कार(&#9661;), अनुस्वार(&darr;)</p><p><strong>प्र.५५) हरणाच्या पिल्लाचे नाव कसे लिहाल?</strong></p>",
