      "subject": "बुद्धिमत्ता चाचणी",
      "section": "2",
      "question": "<p><strong>प्र.५८) प &nbsp; भ &nbsp; स &nbsp; र &nbsp; र &nbsp; भ &nbsp; प &nbsp; स &nbsp; र &nbsp; भ &nbsp; र &nbsp; भ &nbsp; स</strong><br>वरील अक्षरमालेत कोणती अक्षरे समान वेळा आली आहेत?</p>",
