      "question_text": "<p><strong>प्र.६६) सोबतच्या आकृतीत कोनांची संख्या किती आहे?</strong></p><div style='text-align:center;margin:10px 0;'><svg width=\"220\" height=\"150\" viewBox=\"0 0 220 150\" xmlns=\"http://www.w3.org/2000/svg\">\n  <polygon points=\"110,20 20,130 200,130\" fill=\"none\" stroke=\"#333\" stroke-width=\"2\"/>\n  <line x1=\"110\" y1=\"20\" x2=\"65\" y2=\"130\" stroke=\"#333\" stroke-width=\"1.5\"/>\n  <line x1=\"110\" y1=\"20\" x2=\"110\" y2=\"130\" stroke=\"#333\" stroke-width=\"1.5\"/>\n  <line x1=\"110\" y1=\"20\" x2=\"155\" y2=\"130\" stroke=\"#333\" stroke-width=\"1.5\"/>\n</svg></div>",
